// ─── File: ModifierRuleDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.modrule;

import java.math.BigDecimal;
import java.util.logging.*;

public class ModifierRuleDemo {
    private static final Logger log = Logger.getLogger(ModifierRuleDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // COMPILE ERROR if a permitted subclass omits final/sealed/non-sealed:
        //   class SavingsAccount extends Account {}   // (Avoid) "sealed, non-sealed or final modifiers expected"
        // Fix: declare exactly one of the three (below SavingsAccount is final).

        SavingsAccount sav = new SavingsAccount("SAV2001", new BigDecimal("1000000"));
        HomeLoan home      = new HomeLoan("LN5001", new BigDecimal("3000000"));
        PromoAccount promo = new PromoAccount("PR7001", new BigDecimal("50000"));

        log.info(() -> "FINAL subtype:      " + sav.id() + " Rs." + sav.balance());
        log.info(() -> "SEALED→final leaf:  " + home.id() + " Rs." + home.balance());
        log.info(() -> "NON-SEALED subtype: " + promo.id() + " Rs." + promo.balance());

        // Record implementing a sealed interface — implicitly final, NO modifier needed.
        Settlement s = new SettledTrade("TRD-1", new BigDecimal("50000"));
        log.info(() -> "Record subtype (implicitly final): " + s.reference());
    }
}

// ─── Would be in model/Account.java ───
sealed abstract class Account permits SavingsAccount, LoanAccount, PromoAccount {
    private final String id; private final BigDecimal balance;
    protected Account(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
    String id() { return id; } BigDecimal balance() { return balance; }
}

// ─── Would be in model/SavingsAccount.java ───
// FINAL: this branch ends here. Omitting `final` would be a compile error.
final class SavingsAccount extends Account {
    SavingsAccount(String id, BigDecimal balance) { super(id, balance); }
}

// ─── Would be in model/LoanAccount.java ───
// SEALED: continues the closure; must have its own permits list.
sealed abstract class LoanAccount extends Account permits HomeLoan {
    LoanAccount(String id, BigDecimal balance) { super(id, balance); }
}

// ─── Would be in model/HomeLoan.java ───
// FINAL leaf under the sealed LoanAccount.
final class HomeLoan extends LoanAccount {
    HomeLoan(String id, BigDecimal balance) { super(id, balance); }
}

// ─── Would be in model/PromoAccount.java ───
// NON-SEALED: deliberately reopened for future, unrestricted extension.
non-sealed class PromoAccount extends Account {
    PromoAccount(String id, BigDecimal balance) { super(id, balance); }
}

// ─── Sealed interface with a RECORD subtype (implicitly final → rule satisfied) ───
sealed interface Settlement permits SettledTrade { String reference(); }
record SettledTrade(String reference, BigDecimal amount) implements Settlement { }
//   ^ no `final` keyword needed: records are implicitly final.

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
